 22→pub struct GapChecker<'a> {
 23→    registry: &'a RequirementRegistry,
 24→    probe: &'a EnvironmentProbe,
 25→    project_root: PathBuf,
 26→    pub(crate) cache: HashMap<String, RequirementStatus>,
 27→}
 28→
 29→impl<'a> GapChecker<'a> {
 30→    /// Create a new gap checker.
 31→    pub fn new(
 32→        registry: &'a RequirementRegistry,
 33→        probe: &'a EnvironmentProbe,
 34→        project_root: &Path,
 35→    ) -> Self {
 36→        Self {
 37→            registry,
 38→            probe,
 39→            project_root: project_root.to_path_buf(),
 40→            cache: HashMap::new(),
 41→        }
 42→    }
 43→
 44→    /// Check all requirements for a step, returning only non-satisfied gaps.
 45→    ///
 46→    /// `provided_requirements` is authoritative — if the environment says
 47→    /// a requirement is provided, skip the check regardless of what the
 48→    /// step's requires list says. Until environments exist, callers pass `None`.
 49→    pub fn check_step(
 50→        &mut self,
 51→        step: &ResolvedStep,
 52→        provided: Option<&HashSet<String>>,
 53→    ) -> Vec<GapResult> {
 54→        let mut gaps = Vec::new();
 55→        for req_name in &step.requires {
 56→            if let Some(provided_set) = provided {
 57→                if provided_set.contains(req_name) {
 58→                    continue;
 59→                }
 60→            }
 61→
 62→            let status = self.check_one(req_name);
 63→            if !status.is_satisfied() {
 64→                gaps.push(GapResult {
 65→                    requirement: req_name.clone(),
 66→                    status,
 67→                });
 68→            }
 69→        }
 70→        gaps
 71→    }
 72→
 73→    /// Check a single requirement, using cache when available.
 74→    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
 75→        if let Some(cached) = self.cache.get(requirement) {
 76→            return cached.clone();
 77→        }
 78→
 79→        let status = self.evaluate(requirement);
 80→        self.cache.insert(requirement.to_string(), status.clone());
 81→        status
 82→    }
 83→
 84→    /// Invalidate a cached result for a specific requirement.
 85→    pub fn invalidate(&mut self, requirement: &str) {
 86→        self.cache.remove(requirement);
 87→    }
 88→
 89→    /// Invalidate all cached results.
 90→    pub fn invalidate_all(&mut self) {
 91→        self.cache.clear();
 92→    }
 93→
 94→    /// Resolve the install dependency chain for a requirement.
 95→    ///
 96→    /// Returns the ordered list of requirements that need to be installed,
 97→    /// with dependencies before dependents. Max depth 5, detects circular deps.
 98→    pub fn resolve_install_deps(&self, requirement: &str) -> Result<Vec<String>, String> {
 99→        let mut chain = Vec::new();
100→        let mut visited = HashSet::new();
101→        self.resolve_deps_recursive(requirement, &mut chain, &mut visited, 0)?;
102→        Ok(chain)
103→    }
104→
105→    fn resolve_deps_recursive(
106→        &self,
107→        requirement: &str,
108→        chain: &mut Vec<String>,
109→        visited: &mut HashSet<String>,
110→        depth: usize,
111→    ) -> Result<(), String> {
112→        const MAX_DEPTH: usize = 5;
113→
114→        if depth > MAX_DEPTH {
115→            return Err(format!(
116→                "Requirement dependency chain exceeds max depth of {} for '{}'",
117→                MAX_DEPTH, requirement
118→            ));
119→        }
120→
121→        if visited.contains(requirement) {
122→            return Err(format!(
123→                "Circular dependency detected: '{}' appears twice in the chain",
124→                requirement
125→            ));
126→        }
127→
128→        let Some(req) = self.registry.get(requirement) else {
129→            // Unknown requirement — add it to chain, let caller handle
130→            if !chain.contains(&requirement.to_string()) {
131→                chain.push(requirement.to_string());
132→            }
133→            return Ok(());
134→        };
135→
136→        visited.insert(requirement.to_string());
137→
138→        // Resolve static dependencies
139→        for dep in &req.depends_on {
140→            self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
141→        }
142→
143→        // Resolve dynamic dependencies
144→        if let Some(install_requires_fn) = req.install_requires {
145→            let ctx = self.build_install_context();
146→            let dynamic_deps = install_requires_fn(&ctx);
147→            for dep in &dynamic_deps {
148→                if !visited.contains(dep) {
149→                    self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
150→                }

  1→//! Shell command execution.
  2→
  3→use crate::error::{BivvyError, Result};
  4→use std::collections::HashMap;
  5→use std::io::{BufRead, BufReader};
  6→use std::path::Path;
  7→use std::process::{Command, Stdio};
  8→use std::sync::mpsc;
  9→use std::thread;
 10→use std::time::{Duration, Instant};
 11→
 12→/// Result of executing a shell command.
 13→#[derive(Debug, Clone)]
 14→pub struct CommandResult {
 15→    /// Exit code (None if killed by signal).
 16→    pub exit_code: Option<i32>,
 17→
 18→    /// Standard output.
 19→    pub stdout: String,
 20→
 21→    /// Standard error.
 22→    pub stderr: String,
 23→
 24→    /// Execution duration.
 25→    pub duration: Duration,
 26→
 27→    /// Whether command succeeded (exit code 0).
 28→    pub success: bool,
 29→}
 30→
 31→impl CommandResult {
 32→    /// Create a success result.
 33→    pub fn success(stdout: String, stderr: String, duration: Duration) -> Self {
 34→        Self {
 35→            exit_code: Some(0),
 36→            stdout,
 37→            stderr,
 38→            duration,
 39→            success: true,
 40→        }
 41→    }
 42→
 43→    /// Create a failure result.
 44→    pub fn failure(
 45→        exit_code: Option<i32>,
 46→        stdout: String,
 47→        stderr: String,
 48→        duration: Duration,
 49→    ) -> Self {
 50→        Self {
 51→            exit_code,
 52→            stdout,
 53→            stderr,
 54→            duration,
 55→            success: false,
 56→        }
 57→    }
 58→}
 59→
 60→/// Options for command execution.
 61→#[derive(Debug, Clone, Default)]
 62→pub struct CommandOptions {
 63→    /// Working directory.
 64→    pub cwd: Option<std::path::PathBuf>,
 65→
 66→    /// Environment variables (merged with system env).
 67→    pub env: HashMap<String, String>,
 68→
 69→    /// Capture stdout (if false, inherits from parent).
 70→    pub capture_stdout: bool,
 71→
 72→    /// Capture stderr (if false, inherits from parent).
 73→    pub capture_stderr: bool,
 74→
 75→    /// Timeout in seconds (None = no timeout).
 76→    pub timeout: Option<u64>,
 77→}
 78→
 79→/// Output line from command execution.
 80→#[derive(Debug, Clone)]
 81→pub enum OutputLine {
 82→    Stdout(String),
 83→    Stderr(String),
 84→}
 85→
 86→/// Callback for streaming output.
 87→pub type OutputCallback = Box<dyn Fn(OutputLine) + Send>;
 88→
 89→/// Execute a shell command.
 90→pub fn execute(command: &str, options: &CommandOptions) -> Result<CommandResult> {
 91→    let start = Instant::now();
 92→
 93→    let shell = detect_shell();
 94→    let shell_flag = shell_flag(&shell);
 95→
 96→    let mut cmd = Command::new(&shell);
 97→    cmd.arg(shell_flag);
 98→    cmd.arg(command);
 99→
100→    // Set working directory
101→    if let Some(cwd) = &options.cwd {
102→        cmd.current_dir(cwd);
103→    }
104→
105→    // Set environment
106→    for (key, value) in &options.env {
107→        cmd.env(key, value);
108→    }
109→
110→    // Configure stdio
111→    if options.capture_stdout {
112→        cmd.stdout(Stdio::piped());
113→    } else {
114→        cmd.stdout(Stdio::inherit());
115→    }
116→
117→    if options.capture_stderr {
118→        cmd.stderr(Stdio::piped());
119→    } else {
120→        cmd.stderr(Stdio::inherit());
121→    }
122→
123→    // Execute
124→    let output = cmd.output().map_err(|_| BivvyError::CommandFailed {
125→        command: command.to_string(),
126→        code: None,
127→    })?;
128→
129→    let duration = start.elapsed();
130→
131→    let stdout = if options.capture_stdout {
132→        String::from_utf8_lossy(&output.stdout).to_string()
133→    } else {
134→        String::new()
135→    };
136→
137→    let stderr = if options.capture_stderr {
138→        String::from_utf8_lossy(&output.stderr).to_string()
139→    } else {
140→        String::new()
141→    };
142→
143→    if output.status.success() {
144→        Ok(CommandResult::success(stdout, stderr, duration))
145→    } else {
146→        Ok(CommandResult::failure(
147→            output.status.code(),
148→            stdout,
149→            stderr,
150→            duration,
151→        ))
152→    }
153→}
154→
155→/// Execute a command and return success/failure.
156→pub fn execute_check(command: &str, cwd: Option<&Path>) -> bool {
157→    let options = CommandOptions {
158→        cwd: cwd.map(|p| p.to_path_buf()),
159→        capture_stdout: true,
160→        capture_stderr: true,
161→        ..Default::default()
162→    };
163→
164→    execute(command, &options)
165→        .map(|r| r.success)
166→        .unwrap_or(false)
167→}
168→
169→/// Execute a command with streaming output.
170→pub fn execute_streaming(
171→    command: &str,
172→    options: &CommandOptions,
173→    callback: OutputCallback,
174→) -> Result<CommandResult> {
175→    let start = Instant::now();
176→
177→    let shell = detect_shell();
178→    let shell_flag = shell_flag(&shell);
179→
180→    let mut cmd = Command::new(&shell);
181→    cmd.arg(shell_flag);
182→    cmd.arg(command);
183→
184→    if let Some(cwd) = &options.cwd {
185→        cmd.current_dir(cwd);
186→    }
187→
188→    for (key, value) in &options.env {
189→        cmd.env(key, value);
190→    }
191→
192→    cmd.stdout(Stdio::piped());
193→    cmd.stderr(Stdio::piped());
194→
195→    let mut child = cmd.spawn().map_err(|_| BivvyError::CommandFailed {
196→        command: command.to_string(),
197→        code: None,
198→    })?;
199→
200→    let stdout = child.stdout.take().unwrap();

200→    let stdout = child.stdout.take().unwrap();
201→    let stderr = child.stderr.take().unwrap();
202→
203→    let (tx, rx) = mpsc::channel();
204→    let tx_stdout = tx.clone();
205→    let tx_stderr = tx;
206→
207→    // Spawn threads to read stdout and stderr
208→    let stdout_handle = thread::spawn(move || {
209→        let reader = BufReader::new(stdout);
210→        let mut output = String::new();
211→        for line in reader.lines().map_while(std::result::Result::ok) {
212→            output.push_str(&line);
213→            output.push('\n');
214→            let _ = tx_stdout.send(OutputLine::Stdout(line));
215→        }
216→        output
217→    });
218→
219→    let stderr_handle = thread::spawn(move || {
220→        let reader = BufReader::new(stderr);
221→        let mut output = String::new();
222→        for line in reader.lines().map_while(std::result::Result::ok) {
223→            output.push_str(&line);
224→            output.push('\n');
225→            let _ = tx_stderr.send(OutputLine::Stderr(line));
226→        }
227→        output
228→    });
229→
230→    // Process output through callback
231→    for line in rx {
232→        callback(line);
233→    }
234→
235→    let stdout_output = stdout_handle.join().unwrap_or_default();
236→    let stderr_output = stderr_handle.join().unwrap_or_default();
237→
238→    let status = child.wait().map_err(|_| BivvyError::CommandFailed {
239→        command: command.to_string(),
240→        code: None,
241→    })?;
242→
243→    let duration = start.elapsed();
244→
245→    if status.success() {
246→        Ok(CommandResult::success(
247→            stdout_output,
248→            stderr_output,
249→            duration,
250→        ))
251→    } else {
252→        Ok(CommandResult::failure(
253→            status.code(),
254→            stdout_output,
255→            stderr_output,
256→            duration,
257→        ))
258→    }
259→}
260→
261→/// Execute a command and collect output without streaming.
262→pub fn execute_quiet(command: &str, cwd: Option<&Path>) -> Result<CommandResult> {
263→    let options = CommandOptions {
264→        cwd: cwd.map(|p| p.to_path_buf()),
265→        capture_stdout: true,
266→        capture_stderr: true,
267→        ..Default::default()
268→    };
269→    execute(command, &options)
270→}
271→
272→/// Detect the current shell.
273→fn detect_shell() -> String {
274→    if cfg!(target_os = "windows") {
275→        std::env::var("COMSPEC").unwrap_or_else(|_| "cmd.exe".to_string())
276→    } else {
277→        std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string())
278→    }
279→}
280→
281→/// Get the flag to pass commands to the shell.
282→///
283→/// Uses `-lic` (interactive login shell) on Unix so that the user's
284→/// full shell environment is available. Tools like mise, asdf, nvm,
285→/// and rbenv are typically activated in `.zshrc`/`.bashrc` (interactive)
286→/// or `.zprofile`/`.bash_profile` (login). Without `-lic`, these tools
287→/// aren't in PATH and step commands fail with "command not found".
288→///
289→/// In CI environments, uses `-lc` (login, non-interactive) to avoid
290→/// `bash: cannot set terminal process group` errors caused by `-i`
291→/// trying to set up job control without a TTY.
292→fn shell_flag(_shell: &str) -> &'static str {
293→    if cfg!(target_os = "windows") {
294→        "/C"
295→    } else if super::is_ci() {
296→        "-lc"
297→    } else {
298→        "-lic"
299→    }
300→}
