  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).
121→    ///
122→    /// Returns `None` if content unchanged (304 Not Modified).
123→    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
124→        let mut request = self.client.get(url);
125→
126→        if let Some(etag) = etag {
127→            request = request.header("If-None-Match", etag);
128→        }
129→
130→        let response = request.send()?;
131→
132→        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
133→            return Ok(None);
134→        }
135→
136→        if !response.status().is_success() {
137→            bail!("HTTP {} fetching {}", response.status(), url);
138→        }
139→
140→        // Check Content-Length if available
141→        if let Some(len) = response.content_length() {
142→            if len > self.max_response_size {
143→                bail!(
144→                    "Response too large ({} bytes, max {} bytes) from {}",
145→                    len,
146→                    self.max_response_size,
147→                    url
148→                );
149→            }
150→        }

  1→//! Git template fetching.
  2→//!
  3→//! Provides functionality for cloning and updating git repositories
  4→//! to fetch templates, with support for specific refs and update detection.
  5→
  6→use anyhow::{bail, Result};
  7→use sha2::{Digest, Sha256};
  8→use std::path::{Path, PathBuf};
  9→
 10→/// Fetches templates from git repositories.
 11→pub struct GitFetcher {
 12→    /// Directory for cloned repositories.
 13→    clone_dir: PathBuf,
 14→}
 15→
 16→/// Information about a git fetch.
 17→#[derive(Debug)]
 18→pub struct GitFetchResult {
 19→    /// Path to the fetched content.
 20→    pub local_path: PathBuf,
 21→    /// Current commit SHA.
 22→    pub commit_sha: String,
 23→}
 24→
 25→impl GitFetcher {
 26→    /// Create a new git fetcher.
 27→    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
 28→        Self {
 29→            clone_dir: clone_dir.into(),
 30→        }
 31→    }
 32→
 33→    /// Get the clone directory.
 34→    pub fn clone_dir(&self) -> &PathBuf {
 35→        &self.clone_dir
 36→    }
 37→
 38→    /// Clone or update a repository.
 39→    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
 40→        let repo_path = self.repo_path(url);
 41→
 42→        if repo_path.exists() {
 43→            self.update_repo(&repo_path, git_ref)?;
 44→        } else {
 45→            self.clone_repo(url, &repo_path, git_ref)?;
 46→        }
 47→
 48→        let commit_sha = self.get_head_sha(&repo_path)?;
 49→
 50→        Ok(GitFetchResult {
 51→            local_path: repo_path,
 52→            commit_sha,
 53→        })
 54→    }
 55→
 56→    /// Check if a repository has new commits.
 57→    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
 58→        let remote_sha = self.resolve_ref(url, git_ref)?;
 59→        Ok(remote_sha != current_sha)
 60→    }
 61→
 62→    /// Get the current commit SHA for a ref using ls-remote.
 63→    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
 64→        let refspec = git_ref.unwrap_or("HEAD");
 65→
 66→        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
 67→        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
 68→        let candidates = if refspec == "HEAD" {
 69→            vec![refspec.to_string()]
 70→        } else {
 71→            vec![
 72→                refspec.to_string(),
 73→                format!("refs/heads/{refspec}"),
 74→                format!("refs/tags/{refspec}"),
 75→            ]
 76→        };
 77→
 78→        for candidate in &candidates {
 79→            let output = std::process::Command::new("git")
 80→                .args(["ls-remote", url, candidate])
 81→                .output()?;
 82→
 83→            if !output.status.success() {
 84→                bail!(
 85→                    "Failed to query remote: {}",
 86→                    String::from_utf8_lossy(&output.stderr)
 87→                );
 88→            }
 89→
 90→            let stdout = String::from_utf8_lossy(&output.stdout);
 91→            if let Some(sha) = stdout
 92→                .lines()
 93→                .next()
 94→                .and_then(|line| line.split_whitespace().next())
 95→            {
 96→                return Ok(sha.to_string());
 97→            }
 98→        }
 99→
100→        bail!("Could not resolve ref '{refspec}' from {url}")
101→    }
102→
103→    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
104→        if let Some(parent) = path.parent() {
105→            std::fs::create_dir_all(parent)?;
106→        }
107→
108→        let mut cmd = std::process::Command::new("git");
109→        cmd.args(["clone", "--depth", "1"]);
110→
111→        if let Some(r) = git_ref {
112→            cmd.args(["--branch", r]);
113→        }
114→
115→        cmd.args([url, &path.to_string_lossy()]);
116→
117→        let output = cmd.output()?;
118→        if !output.status.success() {
119→            bail!(
120→                "Git clone failed: {}",
121→                String::from_utf8_lossy(&output.stderr)
122→            );
123→        }
124→
125→        Ok(())
126→    }
127→
128→    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
129→        let output = std::process::Command::new("git")
130→            .args(["fetch", "origin"])
131→            .current_dir(path)
132→            .output()?;
133→
134→        if !output.status.success() {
135→            bail!(
136→                "Git fetch failed: {}",
137→                String::from_utf8_lossy(&output.stderr)
138→            );
139→        }
140→
141→        let refspec = if let Some(r) = git_ref {
142→            format!("origin/{}", r)
143→        } else {
144→            "origin/HEAD".to_string()
145→        };
146→
147→        let output = std::process::Command::new("git")
148→            .args(["reset", "--hard", &refspec])
149→            .current_dir(path)
