  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)
 30→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json)?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        fs::read_to_string(&entry.content_path).with_context(|| {
 85→            format!(
 86→                "Failed to read cached content from {:?}",
 87→                entry.content_path
 88→            )
 89→        })
 90→    }
 91→
 92→    /// Save entry metadata.
 93→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 94→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 95→        let json = serde_json::to_string_pretty(entry)?;
 96→        fs::write(&meta_path, json)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Update an entry's metadata (e.g., after revalidation).
101→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
102→        self.save_metadata(entry)
103→    }
104→
105→    /// Remove a cached entry.
106→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
107→        let content_path = self.content_path(source_id, template_name);
108→        let meta_path = self.metadata_path(source_id, template_name);
109→
110→        let mut removed = false;
111→
112→        if content_path.exists() {
113→            fs::remove_file(&content_path)?;
114→            removed = true;
115→        }
116→
117→        if meta_path.exists() {
118→            fs::remove_file(&meta_path)?;
119→            removed = true;
120→        }
121→
122→        Ok(removed)
123→    }
124→
125→    /// List all cached entries.
126→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
127→        self.ensure_dir()?;
128→
129→        let mut entries = Vec::new();
130→
131→        for entry in fs::read_dir(&self.root)? {
132→            let entry = entry?;
133→            let path = entry.path();
134→
135→            if path.extension().is_some_and(|e| e == "json") {
136→                if let Ok(json) = fs::read_to_string(&path) {
137→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
138→                        entries.push(cache_entry);
139→                    }
140→                }
141→            }
142→        }
143→
144→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
145→        Ok(entries)
146→    }
147→
148→    /// Clear all cached entries.
149→    pub fn clear(&self) -> Result<usize> {
150→        let entries = self.list()?;
151→        let count = entries.len();
152→
153→        for entry in entries {
154→            let _ = self.remove(&entry.source_id, &entry.template_name);
155→        }
156→
157→        Ok(count)
158→    }
159→
160→    /// Get total cache size in bytes.
161→    pub fn total_size(&self) -> Result<u64> {
162→        let entries = self.list()?;
163→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
164→    }
165→}
