    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_writes_to_same_key_never_corrupt() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let content = format!("content-from-thread-{}", i);
                    store
                        .store("http:test", "shared-template", &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        // After all writes, the entry must be loadable and consistent.
        let entry = store.load("http:test", "shared-template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        assert!(content.starts_with("content-from-thread-"));
        assert_eq!(entry.metadata.size_bytes, content.len() as u64);
        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "shared-template");
    }

    #[test]
    fn concurrent_writes_to_different_keys_all_succeed() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let handles: Vec<_> = (0..10)
            .map(|i| {
                let store = Arc::clone(&store);
                thread::spawn(move || {
                    let name = format!("template-{}", i);
                    let content = format!("content-{}", i);
                    store
                        .store("http:test", &name, &content, 3600)
                        .unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        for i in 0..10 {
            let name = format!("template-{}", i);
            let expected_content = format!("content-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected_content);
            assert_eq!(entry.metadata.size_bytes, expected_content.len() as u64);
        }
    }

    #[test]
    fn store_is_atomic_no_partial_metadata_on_content_failure() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        // First, store a valid entry.
        store
            .store("http:test", "template", "original", 3600)
            .unwrap();

        // Make the content path read-only to force a write failure.
        let content_path = store.content_path("http:test", "template");
        let mut perms = fs::metadata(&content_path).unwrap().permissions();
        #[allow(clippy::permissions_set_readonly_false)]
        perms.set_readonly(true);
        fs::set_permissions(&content_path, perms).unwrap();

        // A second store should fail, but the original entry stays intact.
        let result = store.store("http:test", "template", "corrupted", 3600);
        assert!(result.is_err());

        // Restore permissions for cleanup and verification.
        let mut perms = fs::metadata(&content_path).unwrap().permissions();
        #[allow(clippy::permissions_set_readonly_false)]
        perms.set_readonly(false);
        fs::set_permissions(&content_path, perms).unwrap();

        // Original metadata should still be intact.
        let entry = store.load("http:test", "template").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "original");
    }
}

