#[test]
fn store_is_atomic_metadata_failure_does_not_corrupt_content() {
    let temp = TempDir::new().unwrap();
    let store = CacheStore::new(temp.path());

    // Store an initial valid entry.
    store
        .store("http:test", "template", "short", 3600)
        .unwrap();

    // Make the metadata file read-only so the second store's metadata
    // write fails AFTER the content write would normally succeed.
    let meta_path = store
        .content_path("http:test", "template")
        .with_extension("meta.json");
    let mut perms = fs::metadata(&meta_path).unwrap().permissions();
    perms.set_readonly(true);
    fs::set_permissions(&meta_path, perms.clone()).unwrap();

    // Attempt a second store with different-length content.
    let result = store.store("http:test", "template", "much-longer-new-content", 3600);
    assert!(result.is_err());

    // Restore permissions for cleanup and reading.
    #[allow(clippy::permissions_set_readonly_false)]
    {
        perms.set_readonly(false);
    }
    fs::set_permissions(&meta_path, perms).unwrap();

    // The original entry must still be consistent: content and metadata
    // must agree. With a non-atomic store the content file was already
    // overwritten while metadata still reflects the old "short" value.
    let entry = store.load("http:test", "template").unwrap().unwrap();
    let content = store.read_content(&entry).unwrap();
    assert_eq!(
        entry.metadata.size_bytes,
        content.len() as u64,
        "metadata size_bytes ({}) must match actual content length ({})",
        entry.metadata.size_bytes,
        content.len()
    );
}

