/// Store content and return a cache entry.
///
/// Writes are atomic: content and metadata are written to temporary
/// files first, then renamed into place. If any step fails, the
/// previous cache entry (if any) remains intact.
pub fn store(
    &self,
    source_id: &str,
    template_name: &str,
    content: &str,
    ttl_seconds: u64,
) -> Result<CacheEntry> {
    self.ensure_dir()?;

    let content_path = self.content_path(source_id, template_name);
    let meta_path = self.metadata_path(source_id, template_name);

    let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
        .with_size(content.len() as u64);
    let json = serde_json::to_string_pretty(&entry)?;

    // Write both files to temporaries in the same directory, then
    // rename. rename(2) is atomic on the same filesystem, so readers
    // always see either the old pair or the new pair.
    let mut tmp_content = NamedTempFile::new_in(&self.root)
        .context("Failed to create temp file for cache content")?;
    tmp_content.write_all(content.as_bytes())?;

    let mut tmp_meta = NamedTempFile::new_in(&self.root)
        .context("Failed to create temp file for cache metadata")?;
    tmp_meta.write_all(json.as_bytes())?;

    // Persist renames the temp file to the target path atomically.
    tmp_content
        .persist(&content_path)
        .map_err(|e| e.error)
        .context("Failed to persist cache content")?;
    tmp_meta
        .persist(&meta_path)
        .map_err(|e| e.error)
        .context("Failed to persist cache metadata")?;

    Ok(entry)
}

