            let expected_content = format!("content-{}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected_content);
            assert_eq!(entry.metadata.size_bytes, expected_content.len() as u64);
        }
    }

