        let mut perms = fs::metadata(&meta_path).unwrap().permissions();
        perms.set_readonly(true);
        fs::set_permissions(&meta_path, perms.clone()).unwrap();

        // Attempt a second store with different-length content.
        let result = store.store("http:test", "template", "much-longer-new-content", 3600);
